  <style>
    :root {
      color-scheme: dark;
      --bg: #0a0d16;
      --panel: rgba(16, 22, 38, 0.92);
      --panel-strong: #131b2d;
      --border: rgba(168, 182, 255, 0.18);
      --border-strong: rgba(182, 193, 255, 0.28);
      --text: #f4f7ff;
      --muted: #aab4d6;
      --accent: #8ca7ff;
      --accent-strong: #b4c4ff;
      --danger: #ff6b81;
      --danger-strong: #ff8fa2;
      --success: #7ef0bf;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.5);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(115, 143, 255, 0.25), transparent 34%),
        linear-gradient(180deg, #12192b 0%, var(--bg) 45%, #05070d 100%);
    }

    a,
    button {
      font: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: #ffffff;
      color: #000000;
      transform: translateY(-160%);
      transition: transform 0.2s ease;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem;
    }

    .shell {
      width: min(100%, 70rem);
      display: grid;
      gap: 1.5rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      letter-spacing: 0.14em;
      font-size: 0.78rem;
      text-transform: uppercase;
    }

    .layout {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: minmax(0, 2fr) minmax(18rem, 1fr);
    }

    .card {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(20px);
    }

    .preview-card {
      overflow: hidden;
    }

    .preview-frame {
      aspect-ratio: 4 / 3;
      margin: 0;
      background: #090d18;
      border-bottom: 1px solid var(--border);
    }

    .preview-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .preview-body,
    .meta-card {
      padding: 1.5rem;
    }

    h1,
    h2 {
      margin: 0;
      line-height: 1.1;
    }

    h1 {
      font-size: clamp(2rem, 4vw, 3.6rem);
    }

    .lead,
    .meta-copy,
    .dialog-copy {
      color: var(--muted);
      line-height: 1.6;
    }

    .preview-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      margin-top: 1.5rem;
    }

    .chip-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin-top: 1.25rem;
    }

    .chip {
      padding: 0.45rem 0.75rem;
      border-radius: 999px;
      background: rgba(140, 167, 255, 0.12);
      border: 1px solid rgba(140, 167, 255, 0.2);
      color: var(--accent-strong);
      font-size: 0.92rem;
    }

    .button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-secondary {
      color: var(--text);
      background: rgba(255, 255, 255, 0.04);
      border-color: var(--border);
    }

    .button-danger {
      color: #fff7f8;
      background: linear-gradient(180deg, var(--danger-strong), var(--danger));
      box-shadow: 0 16px 36px rgba(255, 107, 129, 0.28);
    }

    .trigger {
      min-width: 9rem;
    }

    .meta-list {
      margin: 1.25rem 0 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 1rem;
    }

    .meta-list strong {
      display: block;
      margin-bottom: 0.2rem;
      color: var(--accent-strong);
      font-size: 0.92rem;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 600;
    }

    .empty-state[hidden] {
      display: none;
    }

    .empty-state {
      padding: 2rem 1.5rem;
      border-top: 1px solid var(--border);
      background: rgba(126, 240, 191, 0.06);
    }

    dialog {
      width: min(100% - 2rem, 32rem);
      padding: 0;
      border: 1px solid var(--border-strong);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, rgba(18, 26, 44, 0.98), rgba(10, 14, 25, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(3, 5, 12, 0.72);
      backdrop-filter: blur(6px);
    }

    .dialog-inner {
      padding: 1.5rem;
    }

    .dialog-icon {
      width: 3rem;
      height: 3rem;
      display: inline-grid;
      place-items: center;
      border-radius: 50%;
      background: rgba(255, 107, 129, 0.12);
      color: var(--danger-strong);
      border: 1px solid rgba(255, 107, 129, 0.25);
      font-size: 1.35rem;
      margin-bottom: 1rem;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    :focus-visible {
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    @media (max-width: 52rem) {
      .layout {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 36rem) {
      main {
        padding: 1rem;
      }

      .preview-body,
      .meta-card,
      .dialog-inner,
      .empty-state {
        padding: 1.25rem;
      }

      .preview-actions,
      .dialog-actions {
        flex-direction: column;
      }

      .preview-actions .button,
      .dialog-actions .button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      dialog,
      .button,
      .chip,
      .dialog-icon {
        border: 1px solid CanvasText;
      }

      .button-danger,
      .button-secondary,
      .chip,
      .dialog-icon,
      .empty-state {
        forced-color-adjust: none;
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
