              alt="Sunset over layered mountain ridges with a glowing orange sun."
            >
          </figure>

          <div class="preview-body" id="image-panel">
            <p class="eyebrow">Image preview</p>
            <h1 id="page-title">Golden Hour Ridge</h1>
            <p class="lead">
