              </button>
              <p class="status" id="status-message" aria-live="polite"></p>
            </div>
          </div>

          <section class="empty-state" id="empty-state" hidden aria-labelledby="empty-title">
            <h2 id="empty-title">Image deleted</h2>
            <p class="meta-copy">
              The image has been removed from your library. Your collection is ready for the next upload.
            </p>
          </section>
        </article>

        <aside class="card meta-card" aria-labelledby="details-title">
          <p class="eyebrow">Library details</p>
          <h2 id="details-title">About this file</h2>
          <p class="meta-copy">
