  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-inner">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p class="dialog-copy" id="dialog-description">
        This removes <strong>Golden Hour Ridge</strong> from your library. You can’t undo this action.
      </p>
      <div class="dialog-actions">
        <button type="submit" class="button button-secondary" value="cancel" autofocus>
          Cancel
        </button>
        <button type="submit" class="button button-danger" value="delete">
          Delete image
        </button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('open-dialog');
    const imagePanel = document.getElementById('image-panel');
    const previewImage = document.getElementById('preview-image');
    const emptyState = document.getElementById('empty-state');
    const statusMessage = document.getElementById('status-message');
    const emptyTitle = document.getElementById('empty-title');

    trigger.addEventListener('click', () => {
      dialog.showModal();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue !== 'delete') {
        return;
      }

      imagePanel.hidden = true;
      previewImage.hidden = true;
      emptyState.hidden = false;
      statusMessage.textContent = 'Image removed from your library.';

      if (!document.contains(trigger) || trigger.offsetParent === null) {
        emptyTitle.setAttribute('tabindex', '-1');
        emptyTitle.focus();
      }
    });
  </script>
